import {Cursor as Material} from "./1Adding Interactivity/4UpdatingObjects"
import Root from "./1Adding Interactivity/4UpdatingObjects"
import Sub from "./subReLearn"
import "./ReLearn.css"
import { useState } from "react"

export default function () {
  const [obj, setObj] = useState({nest:{anjas:"ester egg"}})
  const [cursorX, setCursorX] = useState(0)
  const [cursorY, setCursorY] = useState(0)
  return (
    <>
    <div style={{
      width: "93vw",
      height: "97vh"
      }}
      onPointerMove={(e) => {
        setCursorX(e.clientX)
        setCursorX(e.clientX)
      }}
      >
        <div>{cursorX}</div>
        <div>{cursorY}</div>
      </div>
    </>
  );
}



